package com.optarena.app

import java.security.MessageDigest
import java.util.TreeMap

class HashRing(nodes: List<String>, private val replicas: Int) {
    private val ring = TreeMap<Long, String>()

    init {
        nodes.forEach { addNode(it) }
    }

    private fun hashOf(s: String): Long {
        val digest = MessageDigest.getInstance("MD5").digest(s.toByteArray())
        var value = 0L
        for (i in 0 until 8) {
            value = (value shl 8) or (digest[i].toLong() and 0xFF)
        }
        return value and Long.MAX_VALUE
    }

    fun addNode(node: String) {
        for (i in 0 until replicas) {
            ring[hashOf("$node:$i")] = node
        }
    }

    fun removeNode(node: String) {
        for (i in 0 until replicas) {
            ring.remove(hashOf("$node:$i"))
        }
    }

    fun getNode(key: String): String {
        val point = hashOf(key)
        val entry = ring.ceilingEntry(point) ?: ring.firstEntry()
        return entry.value
    }
}

