package com.optarena.app

import org.junit.jupiter.api.Assertions.assertEquals
import org.junit.jupiter.api.Assertions.assertNotEquals
import org.junit.jupiter.api.Assertions.assertTrue
import org.junit.jupiter.api.Test

class HashRingTest {
    @Test
    fun everyKeyMapsToACurrentNode() {
        val ring = HashRing(listOf("a", "b", "c"), 50)
        for (i in 0 until 200) {
            val node = ring.getNode("key-$i")
            assertTrue(node in listOf("a", "b", "c"))
        }
    }

    @Test
    fun deterministic() {
        val ring = HashRing(listOf("a", "b", "c"), 50)
        assertEquals(ring.getNode("stable-key"), ring.getNode("stable-key"))
    }

    @Test
    fun removingANodeOnlyMovesThatNodesOwnKeys() {
        val nodes = listOf("n0", "n1", "n2", "n3", "n4")
        val ring = HashRing(nodes, 100)
        val keys = (0 until 1000).map { "key-$it" }
        val before = keys.associateWith { ring.getNode(it) }

        ring.removeNode("n2")

        var moved = 0
        for (k in keys) {
            val after = ring.getNode(k)
            if (after != before[k]) {
                moved++
                assertEquals("n2", before[k])
            }
            assertNotEquals("n2", after)
        }
        assertTrue(moved > 0)
    }
}
